// Nessacord's look: black and lace, serif type, a photo behind the chat, and the server list tucked
// into the Nessacord menu at the top of the sidebar. The rules are in theme.css; the font, lace,
// photo and mark are embedded in assets.css (generated by tools/make-assets.py).

import { definePluginSettings } from "@api/Settings";
import { classNameFactory, disableStyle, enableStyle } from "@api/Styles";
import ErrorBoundary from "@components/ErrorBoundary";
import definePlugin, { OptionType } from "@utils/types";
import { GuildReadStateStore, useStateFromStores } from "@webpack/common";
import type { KeyboardEvent } from "react";

import assetsStyle from "./assets.css?managed";
import themeStyle from "./theme.css?managed";

const cl = classNameFactory("nessacord-");

const settings = definePluginSettings({
    serverList: {
        type: OptionType.SELECT,
        description: "Where your servers are",
        options: [
            { label: "In the Nessacord menu (click Nessacord at the top left)", value: "menu", default: true },
            { label: "Always shown", value: "always" }
        ],
        onChange: applyClasses
    },
    photo: {
        type: OptionType.BOOLEAN,
        description: "Show the photo behind the chat",
        default: true,
        onChange: applyClasses
    },
    monochromeNames: {
        type: OptionType.BOOLEAN,
        description: "Show names in Nessacord's ivory serif instead of role colours and name styles",
        default: true,
        onChange: applyClasses
    },
    greyscaleAvatars: {
        type: OptionType.BOOLEAN,
        description: "Show avatars in black and white",
        default: true,
        onChange: applyClasses
    },
    serversOpen: {
        type: OptionType.BOOLEAN,
        description: "Whether the Nessacord menu is showing your servers",
        default: false,
        hidden: true,
        onChange: applyClasses
    }
});

function applyClasses() {
    const { serverList, serversOpen, photo, monochromeNames, greyscaleAvatars } = settings.store;
    const root = document.documentElement.classList;

    root.toggle(cl("servers-open"), serverList === "always" || serversOpen);
    root.toggle(cl("servers-always"), serverList === "always");
    root.toggle(cl("no-photo"), !photo);
    root.toggle(cl("mono-names"), monochromeNames);
    root.toggle(cl("grey-avatars"), greyscaleAvatars);
}

function clearClasses() {
    const root = document.documentElement.classList;
    for (const name of ["servers-open", "servers-always", "no-photo", "mono-names", "grey-avatars"]) root.remove(cl(name));
}

function toggleServers() {
    if (settings.store.serverList !== "always") settings.store.serversOpen = !settings.store.serversOpen;
}

function BrandHeader() {
    const { serverList, serversOpen } = settings.use(["serverList", "serversOpen"]);
    const mentions = useStateFromStores([GuildReadStateStore], () => GuildReadStateStore.getTotalMentionCount() - GuildReadStateStore.getPrivateChannelMentionCount());
    const unread = useStateFromStores([GuildReadStateStore], () => GuildReadStateStore.hasAnyUnread());

    const always = serverList === "always";
    const open = always || serversOpen;

    return (
        <div
            className={cl("brand", { "brand-open": open })}
            role={always ? undefined : "button"}
            tabIndex={always ? undefined : 0}
            aria-expanded={always ? undefined : open}
            aria-label={always ? "Nessacord" : open ? "Nessacord: hide servers" : "Nessacord: show servers"}
            onClick={toggleServers}
            onKeyDown={(e: KeyboardEvent) => {
                if (e.key !== "Enter" && e.key !== " ") return;
                e.preventDefault();
                toggleServers();
            }}
        >
            <span className={cl("brand-mark")} />
            <span className={cl("brand-name")}>Nessacord</span>
            {!open && (mentions > 0
                ? <span className={cl("brand-badge")}>{mentions > 99 ? "99+" : mentions}</span>
                : unread && <span className={cl("brand-dot")} />)}
            {!always && (
                <svg className={cl("brand-chevron")} viewBox="0 0 24 24" aria-hidden="true">
                    <path d="M6 9.5l6 6 6-6" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
            )}
        </div>
    );
}

const WrappedBrandHeader = ErrorBoundary.wrap(BrandHeader, { noop: true });

export default definePlugin({
    name: "NessacordTheme",
    description: "Nessacord's look: black and lace, serif type, a photo behind the chat and your servers tucked into the Nessacord menu.",
    authors: [{ name: "deargod", id: 0n }, { name: "bella", id: 0n }],
    enabledByDefault: true,
    settings,

    patches: [
        {
            // Discord's own theme choice (Light, Ash, Dark, Onyx, Sync with computer) never shows
            // through: Discord always renders its Dark theme underneath Nessacord.
            find: 'displayName="ThemeStore"',
            replacement: {
                match: /get theme\(\)\{return \i\}/,
                replace: 'get theme(){return"darker"}'
            }
        },
        {
            // Nor do Nitro colour themes: gradients, custom colours and server themes.
            find: "isClientThemesEditorPreviewActive:",
            replacement: {
                match: /(?<=return function\(\i\)\{)(?=let\{guildCSS:)/,
                replace: 'return{clientThemesCSS:"",clientThemesClassName:""};'
            }
        },
        {
            // The sidebar: the Nessacord menu goes on top of the channel list (or the DM list).
            find: '"Resize Sidebar"',
            replacement: {
                match: /("data-collapsed":\i,.{0,400}?\{\.\.\.\i,children:)(\(0,\i\.jsx\)\(\i,\{\}\))/,
                replace: "$1[$self.renderBrandHeader(),$2]"
            }
        }
    ],

    renderBrandHeader: () => <WrappedBrandHeader key="nessacord-brand" />,

    start() {
        enableStyle(assetsStyle);
        enableStyle(themeStyle);
        applyClasses();
    },

    stop() {
        disableStyle(themeStyle);
        disableStyle(assetsStyle);
        clearClasses();
    }
});
